namespace docking.widgets.imagepanel.actions;



using docking;
using docking.action;
using docking.action;
using docking.widgets.imagepanel;
using generic.theme;

/**
 * An action to re-center the image on a NavigableImagePanel.
 */
public class ResetTranslationAction : ImagePanelDockingAction {

	private static readonly Icon RECENTER_ICON = new GIcon("icon.widget.imagepanel.reset");

	public ResetTranslationAction(string owner, ImagePanel imagePanel) : base("Recenter", owner, imagePanel)
    {

		setPopupMenuData(new MenuData(new string[] { "Recenter Image" }, "view"));

		setToolBarData(new ToolBarData(RECENTER_ICON));
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!base.isEnabledForContext(context)) {
			return false;
		}
		if (imagePanel.getImage() == null) {
			return false;
		}
		return imagePanel.isTranslated();
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		imagePanel.resetImageTranslation();
	}
}
